insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_theatre3_v1'
from (values
('117.317.c.1.A',3,'A company member designs a pre-show routine that raises energy, loosens the voice and focuses the ensemble. She is applying what?','["Preparation and warm-up techniques effectively", "Set storage", "Ticket policies", "Costume budgets"]'::jsonb,0,'Effective warm-ups prepare body, voice and mind.','original'),
('117.317.c.1.A',3,'Why might an ensemble add a focus game to the warm-up before a tense scene?','["To avoid blocking", "To sharpen concentration and group connection", "To reduce rehearsal", "To skip notes"]'::jsonb,1,'Focus games unify the cast.','original'),
('117.317.c.1.B',3,'An actor tries walking a scene at three different tempos and with different centers of gravity to see what feels true. She is doing what?','["Painting scenery", "Skipping rehearsal", "Experimenting with stage movement", "Copying a film"]'::jsonb,2,'Experimentation finds expressive choices.','original'),
('117.317.c.1.B',3,'Which choice is an experiment with stage movement?','["Memorizing a different play", "Repainting a flat", "Changing the lighting cue", "Trying the same line while crossing, then while standing still"]'::jsonb,3,'Testing movement options reveals meaning.','original'),
('117.317.c.1.C',3,'An actor lifts her pitch at the end of a line to show uncertainty. This vocal technique is ___.','["Inflection", "Cueing", "Projection", "Diction"]'::jsonb,0,'Inflection is change in pitch.','original'),
('117.317.c.1.C',3,'Which technique helps lines carry to the last row without shouting?','["Speaking into the floor", "Projection supported by breath", "Mumbling", "Holding the breath"]'::jsonb,1,'Projection uses support, not volume alone.','original'),
('117.317.c.1.D',4,'A student argues that a play''s tragic ending results from the hero''s fatal flaw. She is evaluating its ___.','["Playbill order", "Ticket pricing", "Dramatic structure and genre", "Costume budget"]'::jsonb,2,'Hamartia is a tragic feature.','original'),
('117.317.c.1.D',4,'Which structural element marks the turning point of a play?','["The playbill", "The preset", "The strike", "The climax"]'::jsonb,3,'The climax is the high point and turn.','original'),
('117.317.c.1.E',3,'A soliloquy on stage is replaced in film by a close-up voice-over. This shows differences in what?','["Theatrical conventions across media", "Seat prices", "Lobby design", "Costume sizes"]'::jsonb,0,'Media use different conventions.','original'),
('117.317.c.1.E',3,'Which convention is distinctive to film rather than live theatre?','["Curtain call", "Editing between camera shots", "Live audience presence", "Intermission"]'::jsonb,1,'Editing is a film technique.','original'),
('117.317.c.1.F',4,'A critic notes that the production''s costumes, lighting and sound all reinforced the same theme. She is evaluating what?','["Seat comfort", "Ticket cost", "The interdependence of theatrical elements", "Parking"]'::jsonb,2,'Elements work together.','original'),
('117.317.c.1.F',4,'Which situation shows interdependence of theatrical elements?','["A seat is empty", "A program is misprinted", "A ticket is sold", "A fog effect changes how lighting and costume colors read"]'::jsonb,3,'One element alters another.','original'),
('117.317.c.1.G',3,'A cast member records her scene partner''s lines and plays them back while rehearsing her responses. She is practicing what?','["Memorization skills", "Poster design", "Ticket sales", "Costume changes"]'::jsonb,0,'Recorded cues aid memorization.','original'),
('117.317.c.1.G',3,'Why do actors learn lines in the context of action?','["It removes feeling", "Movement and intention help anchor memory", "It confuses cues", "It slows learning"]'::jsonb,1,'Action supports recall.','original'),
('117.317.c.2.A',3,'Before a scene that demands screaming, an actor works with the director on a technique that protects her voice. She is using what?','["Silence", "Careless habits", "Safe, appropriate techniques for vocal expression", "Strain"]'::jsonb,2,'Safe vocal technique prevents injury.','original'),
('117.317.c.2.A',3,'Which approach supports emotional safety in an intense rehearsal?','["Ignoring discomfort", "Pushing through every limit", "Rehearsing in secret", "Agreeing on check-ins and a way to pause"]'::jsonb,3,'Check-ins protect well-being.','original'),
('117.317.c.2.B',4,'An ensemble notices that audiences lean forward when the cast moves in unison. The group is analyzing creativity and its what?','["Effect on the audience", "Weight of the set", "Length of the run", "Cost to the box office"]'::jsonb,0,'Creative choices affect audiences.','original'),
('117.317.c.2.B',4,'Which question analyzes how a creative choice affects an audience?','["What did tickets cost?", "How did the sudden blackout change the audience''s reaction?", "How long was the line?", "Where did crew park?"]'::jsonb,1,'Reaction to choices matters.','original'),
('117.317.c.2.C',3,'A student compares a naturalistic character with a highly stylized commedia character, noting differences in physicality. She is analyzing what?','["Box office hours", "Seat maps", "Characters from various genres and styles", "Costume sizes"]'::jsonb,2,'Analysis spans styles.','original'),
('117.317.c.2.C',3,'Which detail describes a character''s emotional attributes?','["She carries a bag", "She is five feet tall", "She wears boots", "She hides her fear behind a confident smile"]'::jsonb,3,'Emotions are internal traits.','original'),
('117.317.c.2.D',3,'A group tries the same scene improvised, then scripted, then in a heightened style, to find believable choices. They are experimenting with what?','["Improvisation and scripted scenes of various styles", "Painting a mural", "Reading a playbill", "Selling tickets"]'::jsonb,0,'Varied approaches build believability.','original'),
('117.317.c.2.D',3,'What makes an improvised character believable?','["Copying a movie scene", "Specific wants, history and consistent choices", "No reaction", "Random shouting"]'::jsonb,1,'Specifics create believability.','original'),
('117.317.c.2.E',4,'A playwright writes a line in which a nervous character reveals her secret while also telling the audience what happened before the scene. The dialogue does what?','["Lists the cast", "Sets ticket prices", "Reveals motivation and provides exposition", "Describes lighting"]'::jsonb,2,'Dialogue can serve several functions.','original'),
('117.317.c.2.E',4,'Which feature makes dialogue advance the plot?','["A line about the weather", "A repeated greeting", "A long stage direction", "A line that changes what a character wants or does next"]'::jsonb,3,'Plot-advancing dialogue shifts events.','original'),
('117.317.c.2.F',3,'A group combines live music, projected images and movement in one scene. They are doing what?','["Integrating two or more art or media forms", "Using one medium", "Avoiding collaboration", "Reciting lines only"]'::jsonb,0,'Multimedia work blends forms.','original'),
('117.317.c.2.F',3,'Which pairing integrates art forms in a performance?','["A seating chart", "Dance with spoken poetry and live percussion", "A ticket booth", "A script alone"]'::jsonb,1,'Combining forms enriches meaning.','original'),
('117.317.c.3.A',3,'A student experiments with a gel color on a spotlight during an improvised scene to see how mood changes. She is doing what?','["Damaging equipment", "Ignoring tech", "Experimenting with technical elements safely and effectively", "Skipping safety"]'::jsonb,2,'Safe experiments inform design.','original'),
('117.317.c.3.A',3,'Before hanging a light, a student should do what?','["Hang it quickly", "Stand on a chair", "Skip checking", "Check the safety cable, clamps and power off"]'::jsonb,3,'Safe rigging prevents accidents.','original'),
('117.317.c.3.B',4,'A designer analyzes a script''s setting, themes and cultural context to determine the set''s style. She is treating the text as what?','["A basis for technical discussions", "A budget", "A puzzle only", "A distraction"]'::jsonb,0,'Texts guide design.','original'),
('117.317.c.3.B',4,'Why should a designer consider a play''s themes when choosing color palettes?','["Themes never matter", "Color can reinforce the message and mood", "Color is random", "Color is unimportant"]'::jsonb,1,'Design supports theme.','original'),
('117.317.c.3.C',3,'A student casts two actors in a duet scene and guides them through blocking and character choices. She is doing what?','["Designing posters", "Painting the set", "Casting and directing a duet scene", "Selling tickets"]'::jsonb,2,'Directing includes casting and staging.','original'),
('117.317.c.3.C',3,'When casting a duet scene, a director should consider what?','["Only seat location", "Only height", "Only hair color", "Chemistry and range suited to the roles"]'::jsonb,3,'Casting considers fit and chemistry.','original'),
('117.317.c.3.D',3,'A student serves as lighting designer for a one-act, choosing cues with the director. She is doing what?','["Performing a role in production decisions", "Watching", "Ignoring", "Selling"]'::jsonb,0,'Roles shape production decisions.','original'),
('117.317.c.3.D',3,'The costume designer''s chief task is to do what?','["Operate the sound board", "Create costumes that fit the characters and concept", "Direct actors", "Write dialogue"]'::jsonb,1,'Costume design supports story.','original'),
('117.317.c.3.E',3,'A student stage manager keeps a calm tone, calls cues accurately and solves a missing-prop crisis. She is showing what?','["Panic", "Disorder", "Responsibility, artistic discipline and creative problem solving", "Avoidance"]'::jsonb,2,'Reliable calm supports a show.','original'),
('117.317.c.3.E',3,'Artistic discipline means doing what?','["Missing notes", "Ignoring the schedule", "Skipping when tired", "Showing up prepared and committing to the work"]'::jsonb,3,'Discipline sustains quality.','original'),
('117.317.c.4.A',4,'A student evaluates how the Harlem Renaissance shaped plays of its time. She is evaluating what?','["Historical and cultural influences on theatre", "A casting error", "A set malfunction", "A ticket price"]'::jsonb,0,'Culture shapes theatre.','original'),
('117.317.c.4.A',4,'Evaluating the influence of the Industrial Revolution on stage technology involves what?','["Ignoring technology", "Considering how new machinery changed staging", "Counting seats", "Selling playbills"]'::jsonb,1,'Technology shaped staging.','original'),
('117.317.c.4.B',3,'A student observes that actors in commercials, series and school plays use similar emotional tools. This shows what?','["No overlap", "Isolation", "Theatre, television and film influence daily life", "Silence"]'::jsonb,2,'Acting appears across media.','original'),
('117.317.c.4.B',3,'Which example shows media influencing daily life?','["An empty seat", "A bare stage", "A closed theatre", "Slang from a popular show entering everyday speech"]'::jsonb,3,'Media shape language.','original'),
('117.317.c.4.C',4,'A group performs a scene live, films it, then compares audience reactions to each. They are employing and evaluating the impact of what?','["Live theatre and film in contrasting contexts", "Ticket sales", "Lobby art", "Seat cushions"]'::jsonb,0,'Contexts change impact.','original'),
('117.317.c.4.C',4,'Which advantage does a film version have over live performance?','["Real-time risk", "Close-ups can show subtle facial expressions", "Live audience reactions", "A shared live space"]'::jsonb,1,'Film can magnify detail.','original'),
('117.317.c.4.D',3,'A student researches how Sanskrit drama and Chinese opera influenced theatre. She is researching what?','["Ticket sales", "Parking", "World drama and its influences", "Costume sizing"]'::jsonb,2,'World theatre shapes practice.','original'),
('117.317.c.4.D',3,'Which Greek playwright wrote Antigone?','["Molière", "Ibsen", "Shakespeare", "Sophocles"]'::jsonb,3,'Sophocles wrote Antigone.','original'),
('117.317.c.4.E',3,'A student investigates the contributions of Latino playwrights to U.S. theatre. She is researching what?','["The multicultural heritage of drama in the United States", "Costume history only", "One genre only", "Ancient theatre only"]'::jsonb,0,'U.S. theatre includes many heritages.','original'),
('117.317.c.4.E',3,'Which dramatist wrote Zoot Suit, a landmark Chicano play?','["Arthur Miller", "Luis Valdez", "Neil Simon", "August Wilson"]'::jsonb,1,'Valdez wrote Zoot Suit.','original'),
('117.317.c.4.F',3,'The Federal Theatre Project of the 1930s is an example of what?','["An ancient ritual", "A film studio", "A U.S. contribution to the performing arts", "A European tradition"]'::jsonb,2,'It was a U.S. program supporting theatre.','original'),
('117.317.c.4.F',3,'Which American form combines song, dance and story on Broadway?','["Kabuki", "Passion play", "Noh", "The musical"]'::jsonb,3,'The musical is a U.S. innovation.','original'),
('117.317.c.5.A',2,'A student compares behavior at a rock concert and at a quiet recital, then chooses behavior that fits each. She is doing what?','["Practicing appropriate audience etiquette", "Ignoring context", "Disrespecting performers", "Acting randomly"]'::jsonb,0,'Etiquette depends on the event.','original'),
('117.317.c.5.A',2,'Why is etiquette different for a school assembly and a formal play?','["Etiquette never changes", "Each event has its own expectations", "Rules are random", "Only actors matter"]'::jsonb,1,'Different events call for different behavior.','original'),
('117.317.c.5.B',3,'A student describes how a role pushed her to grow as a performer and where she wants to improve next. She is doing what?','["Ignoring feedback", "Avoiding reflection", "Evaluating herself as a creative being", "Copying others"]'::jsonb,2,'Self-evaluation builds artistry.','original'),
('117.317.c.5.B',3,'What makes theatre count as an art form rather than only a pastime?','["It involves no communication", "It sells snacks", "It requires no practice", "It uses creative expression to communicate ideas and emotions"]'::jsonb,3,'Art communicates meaning.','original'),
('117.317.c.5.C',4,'A student applies a rubric about clarity of storytelling and use of design to review a film and a school play. She is applying what?','["Concepts of evaluation to different performances", "Ignoring criteria", "Gossip", "Guessing"]'::jsonb,0,'Evaluation uses criteria.','original'),
('117.317.c.5.C',4,'Which statement applies evaluation concepts to a TV drama?','["It was fine", "The editing rhythm heightened tension in the chase sequence", "I do not know", "It was on late"]'::jsonb,1,'Specific evaluation cites technique.','original'),
('117.317.c.5.D',4,'A student contrasts how a story is told in a play, a painting and a dance. She is comparing what?','["Parking rules", "Seat counts", "Communication methods across art forms", "Ticket prices"]'::jsonb,2,'Each form communicates differently.','original'),
('117.317.c.5.D',4,'Which feature is unique to theatre compared with a painting?','["Brush texture", "A static image", "A fixed canvas", "Live performers conveying story over time"]'::jsonb,3,'Theatre unfolds in time.','original'),
('117.317.c.5.E',3,'A student weighs pay, training and job outlook for being a lighting designer or drama teacher. She is doing what?','["Making judgments about career opportunities", "Avoiding research", "Guessing", "Ignoring options"]'::jsonb,0,'Judging careers uses evidence.','original'),
('117.317.c.5.E',3,'Which factor should be weighed when judging a theatre career?','["Shoe size", "Training required and job availability", "Favorite color", "Weather forecast"]'::jsonb,1,'Career choices rely on realistic factors.','original'),
('117.317.c.5.F',3,'A student builds a website with a research paper, rehearsal videos and journals about her theatre work. She is using what?','["A paper airplane", "A lighting gel", "Technology to document and present theatre experiences", "A coupon"]'::jsonb,2,'Portfolios present experiences.','original'),
('117.317.c.5.F',3,'Which is a strong use of a digital theatre journal?','["Deleting notes", "Hiding scripts", "Storing coupons", "Recording reflections and goals after each rehearsal"]'::jsonb,3,'Journals track growth.','original'),
('117.317.c.5.G',3,'Collaboration, communication and problem solving learned in theatre are valued in which setting?','["College and many careers", "Only schools", "Nowhere", "Only theatres"]'::jsonb,0,'These skills transfer.','original'),
('117.317.c.5.G',3,'How might theatre training help a future lawyer?','["It teaches carpentry", "It builds confident public speaking and persuasion", "It prevents reading", "It removes research"]'::jsonb,1,'Speaking skills transfer to law.','original'),
('117.317.c.5.H',3,'A student compiles a one-page list of her roles, crew jobs and training. She is creating a ___.','["Set model", "Cue sheet", "Theatre resume", "Ticket stub"]'::jsonb,2,'Resumes summarize experience.','original'),
('117.317.c.5.H',3,'Which belongs in a personal theatre portfolio?','["Receipts", "Weather logs", "Bus schedules", "Headshot, resume and performance clips"]'::jsonb,3,'Portfolios document experience.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
